class Solution:

	def betterString(self, str1, str2):

		def find(str1):
			count = 1
			dic = {}
			for el in str1:
				if el not in dic:
					dic[el] = count
					count *= 2
				elif el in dic:
					temp = dic[el]
					dic[el] = count
					count *= 2
					count -= temp
			return count
		cnt1 = find(str1)
		cnt2 = find(str2)
		if cnt1 >= cnt2:
			return str1
		return str2
